76	
77	fn build_runtime(args: &Args) -> Result<RuntimeConfig> {
78	    if let Some(path) = &args.profile {
79	        ensure_legacy_timing_flags_are_absent(args)?;
80	        let profile = EngineProfile::load_from_path(path)
81	            .with_context(|| format!("failed to load engine profile {}", path.display()))?;
82	        let model_id = profile.model_id().to_string();
83	        if let Some(requested) = &args.model_id {
84	            ensure!(
85	                requested == profile.model_id(),
86	                "--model-id '{}' conflicts with profile model_id '{}'",
87	                requested,
88	                profile.model_id()
89	            );
90	        }
91	        if let Some(requested) = args.max_model_len {
92	            ensure!(
93	                requested == profile.scheduler.max_model_len,
94	                "--max-model-len {} conflicts with profile max_model_len {}",
95	                requested,
96	                profile.scheduler.max_model_len
97	            );
98	        }
99	        let engine = SimulatedEngineConfig::default()
100	            .with_fallback_token_id(args.fallback_token_id)
101	            .with_engine_profile(profile.clone())?;
102	        let model_path = args.model_path.clone().unwrap_or_else(|| {
103	            args.model_id
104	                .as_deref()
105	                .map_or_else(|| PathBuf::from(&model_id), PathBuf::from)
106	        });
107	        return Ok(RuntimeConfig {
108	            engine,
109	            model_path,
110	            served_model_name: vec![model_id],
111	            max_model_len: profile.scheduler.max_model_len,
112	            profile: Some(profile),
113	        });
114	    }
115	    let model_id = args
116	        .model_id
117	        .clone()
118	        .or_else(|| {
119	            args.model_path
120	                .as_deref()
121	                .map(|path| path.to_string_lossy().into_owned())
122	        })
123	        .unwrap_or_else(|| DEFAULT_MODEL_ID.to_string());
124	    let model_path = args
125	        .model_path
126	        .clone()
127	        .unwrap_or_else(|| PathBuf::from(&model_id));
128	    let max_model_len = args.max_model_len.unwrap_or(DEFAULT_MAX_MODEL_LEN);
129	    ensure!(max_model_len > 0, "max_model_len must be positive");
130	    let base_ttft_ms = args.base_ttft_ms.unwrap_or(DEFAULT_BASE_TTFT_MS);
131	    let prefill_tokens_per_ms = args
132	        .prefill_tokens_per_ms
133	        .unwrap_or(DEFAULT_PREFILL_TOKENS_PER_MS);
134	    let tpot_ms = args.tpot_ms.unwrap_or(DEFAULT_TPOT_MS);
135	    let engine = SimulatedEngineConfig::new(
136	        base_ttft_ms,
137	        prefill_tokens_per_ms,
138	        tpot_ms,
139	        args.fallback_token_id,
140	    )?;
141	    Ok(RuntimeConfig {
142	        engine,
143	        model_path,
144	        served_model_name: if args.model_path.is_some() && args.model_id.is_some() {
145	            vec![model_id]
146	        } else {
147	            Vec::new()
148	        },
149	        max_model_len,
150	        profile: None,
151	    })
152	}
153	
154	fn ensure_legacy_timing_flags_are_absent(args: &Args) -> Result<()> {
155	    let provided = [
156	        ("--base-ttft-ms", args.base_ttft_ms.is_some()),
157	        (
158	            "--prefill-tokens-per-ms",
159	            args.prefill_tokens_per_ms.is_some(),
160	        ),
161	        ("--tpot-ms", args.tpot_ms.is_some()),
162	    ];
163	    if let Some((name, true)) = provided.into_iter().find(|(_, present)| *present) {
164	        bail!("{name} cannot be combined with --profile; timing comes from the profile");
165	    }
166	    Ok(())
167	}
168	
169	fn report_profile(runtime: &RuntimeConfig) {
170	    let Some(profile) = &runtime.profile else {
171	        eprintln!("active engine profile: legacy fixed TTFT/TPOT scheduler");
172	        return;
173	    };
174	    let scheduler = &profile.scheduler;
175	    eprintln!(
176	        "active engine profile: path={} manifest={} manifest_sha256={} target={} version={} model={} revision={} gpu={} scheduler={:?} max_num_seqs={} max_num_batched_tokens={} max_model_len={} predictor_coverage={:?}",
177	        profile.profile_path.display(),
178	        profile.manifest_path.display(),
179	        profile.calibration.sha256,
180	        profile.manifest.target_engine,
181	        profile.manifest.engine_version,
182	        profile.manifest.model_id,
183	        profile.manifest.model_revision,
184	        profile.manifest.gpu,
185	        scheduler.policy,
186	        scheduler.max_num_seqs,
187	        scheduler.max_num_batched_tokens,
188	        scheduler.max_model_len,
189	        profile.predictor.coverage.domain(),
190	    );
191	}
192	
193	fn init_logging() {
194	    LOGGING_INIT.call_once(|| {
195	        let filter_spec = std::env::var("RUST_LOG").unwrap_or_else(|_| "info".to_string());
196	        let filter = logforth::filter::env_filter::EnvFilterBuilder::from_spec(filter_spec).build();
197	        logforth::starter_log::builder()
198	            .dispatch(|dispatch| {
199	                dispatch
200	                    .filter(filter)
201	                    .append(logforth::append::Stderr::default())
202	            })
203	            .apply();
204	    });
205	}
206	
207	#[tokio::main]
208	async fn main() -> Result<()> {
209	    init_logging();
210	    let args = Args::parse();
211	    let runtime = build_runtime(&args)?;
212	    report_profile(&runtime);
213	    let engine = start_engine(&runtime.engine);
214	
215	    pegainfer_frontend::vllm::serve(
216	        std::future::ready(Ok(engine.into())),
217	        &runtime.model_path,
218	        runtime.served_model_name,
219	        pegainfer_frontend::vllm::ParserSelection::Auto,
220	        args.port,
221	        Some(runtime.max_model_len),
222	        pegainfer_frontend::vllm::shutdown_token_from_ctrl_c(),
223	    )
224	    .await
225	}
