68	impl SimulatedEngineConfig {
69	    pub fn new(
70	        base_ttft_ms: f64,
71	        prefill_tokens_per_ms: f64,
72	        tpot_ms: f64,
73	        fallback_token_id: u32,
74	    ) -> Result<Self> {
75	        ensure!(
76	            base_ttft_ms.is_finite() && base_ttft_ms >= 0.0,
77	            "base TTFT must be finite and non-negative"
78	        );
79	        ensure!(
80	            prefill_tokens_per_ms.is_finite() && prefill_tokens_per_ms > 0.0,
81	            "prefill throughput must be finite and positive"
82	        );
83	        ensure!(
84	            tpot_ms.is_finite() && tpot_ms >= 0.0,
85	            "TPOT must be finite and non-negative"
86	        );
87	
88	        Ok(Self {
89	            base_ttft_ms,
90	            prefill_tokens_per_ms,
91	            tpot_ms,
92	            fallback_token_id,
93	            scripted_completion: Vec::new(),
94	            spec_decode: None,
95	            profile: None,
96	            prefix_cache: None,
97	        })
98	    }
99	
100	    /// Make every decode step a verify step, so the metrics path has a drafter
101	    /// without a GPU or a checkpoint. Panics on a `K` past `MAX_SPEC_TOKENS`.
102	    #[must_use]
103	    pub fn with_speculative_decoding(
104	        mut self,
105	        num_spec_tokens: usize,
106	        num_accepted: usize,
107	    ) -> Self {
108	        assert!(
109	            num_accepted <= num_spec_tokens,
110	            "a verify step cannot accept more draft tokens than it proposed"
111	        );
112	        SpecDecodeCounters::new(num_spec_tokens).expect("K within MAX_SPEC_TOKENS");
113	        self.spec_decode = Some((num_spec_tokens, num_accepted));
114	        self
115	    }
