117	    /// Report a prefix-cache lookup on every ordinary request's first chunk:
118	    /// `hit_tokens` served from local KV and `external_hit_tokens` restored
119	    /// from the connector (CPU offload / P2P) instead. Hit 0 models a miss.
120	    #[must_use]
121	    pub fn with_prefix_cache(mut self, hit_tokens: usize, external_hit_tokens: usize) -> Self {
122	        self.prefix_cache = Some((hit_tokens, external_hit_tokens));
123	        self
124	    }
125	
126	    /// Replay `ids` verbatim as the completion for every request
127	    #[must_use]
