561	    fn metrics(&self, spec_decode: Option<&SpecDecodeCounters>) -> SchedulerMetrics {
562	        SchedulerMetrics {
563	            num_running_reqs: self.worker.running_len() as u64,
564	            num_waiting_reqs: self.worker.waiting_len() as u64,
565	            spec_decode: spec_decode.copied(),
566	            ..SchedulerMetrics::default()
567	        }
568	    }
569	}
