644	        if let Some(profiled) = &self.profiled {
645	            // The profiled lane drives its own run state, but the prefix-cache
646	            // counters are tallied on admission whichever lane admits the
647	            // request, so both lanes report them the same way.
648	            let mut metrics = profiled.metrics(self.spec_decode.as_ref());
649	            metrics.prefix_cache = self.prefix_cache_counters();
650	            return metrics;
651	        }
652	        SchedulerMetrics {
653	            num_running_reqs: self.running.len() as u64,
654	            num_waiting_reqs: self.queued.len() as u64,
655	            spec_decode: self.spec_decode,
656	            prefix_cache: self.prefix_cache_counters(),
657	            ..SchedulerMetrics::default()
658	        }
659	    }
