786	fn duration_from_ms(ms: f64) -> Result<Duration> {
787	    ensure!(
788	        ms.is_finite() && ms >= 0.0,
789	        "timing value must be finite and non-negative"
790	    );
791	    Duration::try_from_secs_f64(ms / 1000.0)
792	        .context("timing value is not representable as a Duration")
793	}
794	
795	fn duration_from_us(microseconds: u64) -> Duration {
796	    Duration::new(
797	        microseconds / 1_000_000,
798	        ((microseconds % 1_000_000) * 1_000) as u32,
799	    )
800	}
