978	        let mut runtime = ProfiledRuntime::new(&ProfileConfig { profile });
979	        let request_id = RequestId::new(7);
980	        let survivor_id = RequestId::new(8);
981	        runtime
982	            .worker
983	            .submit(WorkerRequest {
