1003	        assert!(runtime.worker.request(survivor_id).is_some());
1004	
1005	        runtime.cancel_worker_requests(&[request_id]).unwrap();
1006	        assert!(runtime.worker.request(request_id).is_none());
1007	
1008	        let survivor_step_id = runtime.worker.plan_step().unwrap().unwrap().id();
1009	        let survivor_outcome = runtime.worker.complete_step(survivor_step_id).unwrap();
1010	        assert_eq!(survivor_outcome.finished, [survivor_id]);
1011	        assert!(runtime.worker.request(survivor_id).is_none());
1012	    }
