206	    next_step_id: u64,
207	}
208	
209	impl<I> WorkerState<I>
210	where
211	    I: Copy + Eq,
212	{
213	    pub fn new(scheduler: SchedulerProfile) -> Result<Self> {
214	        scheduler.validate()?;
215	        Ok(Self {
216	            scheduler,
217	            waiting: VecDeque::new(),
218	            running: Vec::new(),
219	            in_flight: None,
220	            next_step_id: 0,
221	        })
222	    }
223	
224	    #[must_use]
225	    pub fn scheduler(&self) -> &SchedulerProfile {
226	        &self.scheduler
227	    }
228	
229	    pub(crate) fn preflight(
230	        &self,
231	        prompt_tokens: u32,
232	        output_tokens: u64,
233	    ) -> Option<RequestRejection> {
234	        let total_tokens = u64::from(prompt_tokens).saturating_add(output_tokens);
235	        if total_tokens > u64::from(self.scheduler.max_model_len) {
236	            return Some(RequestRejection::ModelLengthExceeded {
237	                total_tokens,
238	                max_model_len: self.scheduler.max_model_len,
239	            });
240	        }
241	        if output_tokens > 0
242	            && self.scheduler.prefill == PrefillPolicy::Whole
243	            && prompt_tokens > self.scheduler.max_num_batched_tokens
244	        {
245	            return Some(RequestRejection::WholePrefillExceedsStepBudget {
246	                prompt_tokens,
247	                max_num_batched_tokens: self.scheduler.max_num_batched_tokens,
248	            });
249	        }
250	        None
251	    }
252	
253	    pub fn submit(&mut self, request: WorkerRequest<I>) -> Result<SubmissionResult> {
254	        ensure!(
255	            self.request(request.id).is_none(),
256	            "worker request id is already active"
257	        );
258	        if let Some(rejection) =
259	            self.preflight(request.prompt_tokens, u64::from(request.output_tokens))
260	        {
261	            return Ok(SubmissionResult::Rejected(rejection));
262	        }
263	        if request.output_tokens == 0 {
264	            return Ok(SubmissionResult::Finished);
265	        }
266	        self.waiting.push_back(RequestState::new(request));
267	        Ok(SubmissionResult::Queued)
268	    }
269	
270	    #[must_use]
271	    pub fn waiting_len(&self) -> usize {
272	        self.waiting.len()
273	    }
274	
275	    #[must_use]
276	    pub fn running_len(&self) -> usize {
277	        self.running.len()
278	    }
