459	    fn interpolate(&self, shape: StepShape) -> Result<Option<u64>> {
460	        let Some(decode) = bracket(&self.decode_reqs, shape.decode_reqs) else {
461	            return Ok(None);
462	        };
463	        let Some(context) = bracket(&self.sum_decode_ctx_tokens, shape.sum_decode_ctx_tokens)
464	        else {
465	            return Ok(None);
466	        };
467	        let Some(prefill) = bracket(&self.prefill_tokens_in_step, shape.prefill_tokens_in_step)
468	        else {
469	            return Ok(None);
470	        };
471	
472	        let d0c0 = interpolate_bracket(
473	            self.value_at(decode.lower, context.lower, prefill.lower)?,
474	            self.value_at(decode.lower, context.lower, prefill.upper)?,
475	            prefill,
476	        )?;
477	        let d0c1 = interpolate_bracket(
478	            self.value_at(decode.lower, context.upper, prefill.lower)?,
479	            self.value_at(decode.lower, context.upper, prefill.upper)?,
480	            prefill,
481	        )?;
482	        let d1c0 = interpolate_bracket(
483	            self.value_at(decode.upper, context.lower, prefill.lower)?,
484	            self.value_at(decode.upper, context.lower, prefill.upper)?,
485	            prefill,
486	        )?;
487	        let d1c1 = interpolate_bracket(
488	            self.value_at(decode.upper, context.upper, prefill.lower)?,
489	            self.value_at(decode.upper, context.upper, prefill.upper)?,
490	            prefill,
491	        )?;
492	        let d0 = interpolate_bracket(d0c0, d0c1, context)?;
493	        let d1 = interpolate_bracket(d1c0, d1c1, context)?;
494	        Ok(Some(interpolate_bracket(d0, d1, decode)?))
495	    }
496	
497	    fn value_at(&self, decode: usize, context: usize, prefill: usize) -> Result<u64> {
498	        let index = decode
499	            .checked_mul(self.sum_decode_ctx_tokens.len())
500	            .and_then(|value| value.checked_add(context))
501	            .and_then(|value| value.checked_mul(self.prefill_tokens_in_step.len()))
502	            .and_then(|value| value.checked_add(prefill))
503	            .context("timing grid index overflow")?;
504	        self.step_duration_us
505	            .get(index)
506	            .copied()
507	            .context("timing grid is missing a duration value")
508	    }
509	}
