532	#[derive(Clone, Copy)]
533	struct AxisBracket {
534	    lower: usize,
535	    upper: usize,
536	    numerator: u64,
537	    denominator: u64,
538	}
539	
540	fn bracket<T>(axis: &[T], value: T) -> Option<AxisBracket>
541	where
542	    T: Copy + Ord + Into<u64>,
543	{
544	    match axis.binary_search(&value) {
545	        Ok(index) => Some(AxisBracket {
546	            lower: index,
547	            upper: index,
548	            numerator: 0,
549	            denominator: 1,
550	        }),
551	        Err(0) => None,
552	        Err(index) if index == axis.len() => None,
553	        Err(index) => {
554	            let lower_value = axis[index - 1].into();
555	            let upper_value = axis[index].into();
556	            Some(AxisBracket {
557	                lower: index - 1,
558	                upper: index,
559	                numerator: value.into() - lower_value,
560	                denominator: upper_value - lower_value,
561	            })
562	        }
563	    }
564	}
565	
566	fn interpolate_bracket(lower: u64, upper: u64, bracket: AxisBracket) -> Result<u64> {
567	    if bracket.lower == bracket.upper || lower == upper {
568	        return Ok(lower);
569	    }
570	    let delta = lower.abs_diff(upper);
571	    let scaled = u128::from(delta)
572	        .checked_mul(u128::from(bracket.numerator))
573	        .context("timing interpolation multiplication overflow")?;
574	    let rounded = scaled
575	        .checked_add(u128::from(bracket.denominator / 2))
576	        .context("timing interpolation rounding overflow")?
577	        / u128::from(bracket.denominator);
578	    let adjustment = u64::try_from(rounded).context("timing interpolation result overflow")?;
579	    if upper >= lower {
580	        lower
581	            .checked_add(adjustment)
582	            .context("timing interpolation addition overflow")
583	    } else {
584	        lower
585	            .checked_sub(adjustment)
586	            .context("timing interpolation subtraction overflow")
587	    }
588	}
