1	//! Tool-call round-trip contract test for the OpenAI `/v1/chat/completions`
2	//! path, driven entirely on CPU through `pegainfer-sim`.
3	//!
4	//! This is the "protocol layer testable on pegainfer-sim" deliverable from the
5	//! coding-agent workstream (roadmap-2026-h2 §5). It does NOT test the upstream
6	//! vLLM tool parser in isolation (upstream already has `roundtrip.rs` for that).
7	//! It tests the seam pegainfer owns: a scripted engine byte stream ->
8	//! pegainfer's `TokenEvent` contract + detokenize -> upstream `Auto` parser
9	//! selection -> OpenAI `tool_calls` output, in both non-streaming and streaming
10	//! form.
11	//!
12	//! Several non-obvious constraints make this work — including two real wiring
13	//! gaps this test caught by failing (the frontend runs a *second* `Auto` parser
14	//! for reasoning; the upstream frontend suppresses the final token id on `Stop`,
15	//! so the script must pad a trailing EOS the engine never actually emits — see
16	//! #584). Each is documented at the code site it justifies rather than in a list
17	//! here, so the rationale stays next to the line it explains and can't drift.
18	
19	use std::fs;
20	use std::net::TcpListener;
21	use std::time::Duration;
22	
23	use anyhow::Context;
24	use anyhow::Result;
25	use anyhow::anyhow;
26	use anyhow::bail;
27	use pegainfer_frontend::vllm::ParserSelection;
28	use pegainfer_sim::SimulatedEngineConfig;
29	use pegainfer_sim::start_engine;
30	use reqwest::Client;
31	use serde_json::Map;
32	use serde_json::Value;
33	use serde_json::json;
34	use tempfile::TempDir;
35	use tokio::task::JoinHandle;
36	use tokio_util::sync::CancellationToken;
37	
38	const HTTP_TIMEOUT: Duration = Duration::from_secs(10);
39	const MODEL_NAME: &str = "pegainfer-sim-toolcall";
40	
41	// The three scripted completion chunks to test toolcall parsing in streaming.
42	// Concatenated they form exactly:
43	//   <tool_call>
44	//   {"name": "get_weather", "arguments": {"location": "SF"}}
45	//   </tool_call>
46	//
47	// The split points fall *inside* the JSON ("argu|ments", "S|F") so the streaming
48	// path must accumulate a tool call across multiple detokenized deltas.
49	const CHUNK_1: &str = "<tool_call>\n{\"name\": \"get_weather\", \"argu";
50	const CHUNK_2: &str = "ments\": {\"location\": \"S";
51	const CHUNK_3: &str = "F\"}}\n</tool_call>";
52	
53	#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
54	async fn non_streaming_tool_call_round_trips_to_openai_tool_calls() -> Result<()> {
55	    let server = ToolCallSimServer::spawn().await?;
56	    let client = test_client()?;
57	
58	    let response = client
59	        .post(format!("{}/v1/chat/completions", server.base_url))
60	        .json(&chat_request(false))
61	        .send()
62	        .await?;
63	    let status = response.status();
64	    let text = response.text().await?;
65	    if !status.is_success() {
66	        bail!("chat completion returned {status}: {text}");
67	    }
68	    let body: Value =
69	        serde_json::from_str(&text).context("failed to parse non-streaming chat response")?;
70	
71	    let tool_calls = body["choices"][0]["message"]["tool_calls"]
72	        .as_array()
73	        .ok_or_else(|| anyhow!("response has no message.tool_calls array: {body}"))?;
74	    if tool_calls.len() != 1 {
75	        bail!(
76	            "expected exactly one tool call, got {}: {body}",
77	            tool_calls.len()
78	        );
79	    }
80	    assert_tool_call_is_get_weather_sf(&tool_calls[0], &body)?;
81	
82	    server.shutdown().await
83	}
84	
85	#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
86	async fn streaming_tool_call_reassembles_across_chunks() -> Result<()> {
87	    let server = ToolCallSimServer::spawn().await?;
88	    let client = test_client()?;
89	
90	    let raw = client
91	        .post(format!("{}/v1/chat/completions", server.base_url))
92	        .json(&chat_request(true))
93	        .send()
94	        .await?
95	        .error_for_status()?
96	        .text()
97	        .await
98	        .context("failed to read streaming chat response")?;
99	
100	    // Accumulate the streamed tool-call name + arguments across SSE frames.
101	    let mut name = String::new();
102	    let mut arguments = String::new();
103	    let mut argument_fragments = 0usize;
104	    let mut saw_done = false;
105	
106	    for line in raw.lines() {
107	        let payload = match line.strip_prefix("data: ") {
108	            Some(p) => p.trim(),
109	            None => continue,
110	        };
111	        if payload == "[DONE]" {
112	            saw_done = true;
113	            continue;
114	        }
115	        let frame: Value = serde_json::from_str(payload)
116	            .with_context(|| format!("failed to parse SSE frame: {payload}"))?;
117	        let Some(deltas) = frame["choices"][0]["delta"]["tool_calls"].as_array() else {
118	            continue;
119	        };
120	        for delta in deltas {
121	            if let Some(n) = delta["function"]["name"].as_str() {
122	                name.push_str(n);
123	            }
124	            if let Some(args) = delta["function"]["arguments"].as_str() {
125	                if !args.is_empty() {
126	                    arguments.push_str(args);
127	                    argument_fragments += 1;
128	                }
129	            }
130	        }
131	    }
132	
133	    if !saw_done {
134	        bail!("streaming tool-call response did not terminate with data: [DONE]:\n{raw}");
135	    }
136	    if name != "get_weather" {
137	        bail!("streamed tool name reassembled to {name:?}, expected \"get_weather\":\n{raw}");
138	    }
139	    // The whole point of this test: the arguments must have arrived in more than
140	    // one delta and still reassemble to valid JSON.
141	    if argument_fragments < 2 {
142	        bail!(
143	            "expected tool-call arguments to stream across >= 2 fragments, got {argument_fragments}:\n{raw}"
144	        );
145	    }
146	    let parsed: Value = serde_json::from_str(&arguments).with_context(|| {
147	        format!("reassembled streamed arguments are not valid JSON: {arguments:?}")
148	    })?;
149	    if parsed["location"] != json!("SF") {
150	        bail!("streamed arguments location != SF: {parsed}");
151	    }
152	
153	    server.shutdown().await
154	}
155	
156	fn assert_tool_call_is_get_weather_sf(tool_call: &Value, body: &Value) -> Result<()> {
157	    if tool_call["type"] != json!("function") {
158	        bail!("tool call is not type=function: {body}");
159	    }
160	    if tool_call["function"]["name"] != json!("get_weather") {
161	        bail!("tool call name != get_weather: {body}");
162	    }
163	    let arguments = tool_call["function"]["arguments"]
164	        .as_str()
165	        .ok_or_else(|| anyhow!("tool call arguments are not a string: {body}"))?;
166	    let parsed: Value = serde_json::from_str(arguments)
167	        .with_context(|| format!("tool call arguments are not valid JSON: {arguments:?}"))?;
168	    if parsed["location"] != json!("SF") {
169	        bail!("tool call arguments location != SF: {parsed}");
170	    }
171	    Ok(())
172	}
173	
174	fn chat_request(stream: bool) -> Value {
175	    json!({
176	        "model": MODEL_NAME,
177	        // Prompt content is irrelevant: scripted mode ignores the prompt tokens
178	        // and replays the tool-call chunks regardless.
179	        "messages": [{ "role": "user", "content": "call the weather tool" }],
180	        "tools": [{
181	            "type": "function",
182	            "function": {
183	                "name": "get_weather",
184	                "description": "Get the weather for a city",
185	                "parameters": {
186	                    "type": "object",
187	                    "properties": { "location": { "type": "string" } },
188	                    "required": ["location"]
189	                }
190	            }
191	        }],
192	        "tool_choice": "auto",
193	        "max_tokens": 16,
194	        "temperature": 0.0,
195	        "stream": stream
196	    })
197	}
198	
199	struct ToolCallSimServer {
200	    base_url: String,
201	    shutdown: CancellationToken,
202	    task: JoinHandle<Result<()>>,
203	    _model_dir: TempDir,
204	}
205	
206	impl ToolCallSimServer {
207	    async fn spawn() -> Result<Self> {
208	        // Script = the three tool-call chunks (ids 1/2/3, see fuse_tokenizer_json)
209	        // plus 6 (EOS). The trailing EOS is *not* incremental-detokenizer buffering:
210	        // the upstream frontend's terminal-stop-token suppression drops the last
211	        // token id whenever a request finishes with `Stop`. pegainfer engines never
212	        // emit an EOS token — they signal `Finished(Stop)` with no preceding token
213	        // event — so without this pad the suppression would eat the final *content*
214	        // token and truncate the JSON to `{"location": "S`. The throwaway EOS
215	        // absorbs the suppression instead. Engine-side contract alignment: #584.
216	        let script = vec![1u32, 2, 3, 6];
217	        let model_dir = qwen_model_dir()?;
218	        let port = reserve_loopback_port()?;
219	        let base_url = format!("http://127.0.0.1:{port}");
220	
221	        let shutdown = CancellationToken::new();
222	        let server_shutdown = shutdown.clone();
223	        let engine = start_engine(
224	            &SimulatedEngineConfig::new(0.0, 1000.0, 0.0, 0)?.with_scripted_completion(script),
225	        );
226	        let model_path = model_dir.path().to_path_buf();
227	        let mut task = tokio::spawn(async move {
228	            pegainfer_frontend::vllm::serve(
229	                std::future::ready(Ok(engine.into())),
230	                &model_path,
231	                vec![MODEL_NAME.to_string()],
232	                ParserSelection::Auto,
233	                port,
234	                Some(128),
235	                server_shutdown,
236	            )
237	            .await
238	        });
239	
240	        let client = test_client()?;
241	        let health = tokio::select! {
242	            result = wait_for_health(&client, &base_url) => result,
243	            result = &mut task => {
244	                return match result {
245	                    Ok(Ok(())) => Err(anyhow!("sim frontend exited before becoming healthy")),
246	                    Ok(Err(error)) => Err(error).context("sim frontend exited before becoming healthy"),
247	                    Err(error) => Err(error).context("sim frontend task panicked"),
248	                };
249	            }
250	        };
251	        if let Err(error) = health {
252	            shutdown.cancel();
253	            let _ = tokio::time::timeout(Duration::from_secs(10), task).await;
254	            return Err(error);
255	        }
256	
257	        Ok(Self {
258	            base_url,
259	            shutdown,
260	            task,
261	            _model_dir: model_dir,
262	        })
263	    }
264	
265	    async fn shutdown(self) -> Result<()> {
266	        self.shutdown.cancel();
267	        tokio::time::timeout(Duration::from_secs(10), self.task)
268	            .await
269	            .context("timed out waiting for sim frontend shutdown")?
270	            .context("sim frontend task panicked")?
271	    }
272	}
273	
274	/// Model dir at a path containing `qwen3`. `ParserSelection::Auto` resolves the
275	/// parser from the *model path string* (`config.model`) by case-insensitive
276	/// substring match against a registry (`qwen3` -> `qwen3_json`) — a random temp
277	/// dir has no model-family name and would fail with `ParserUnavailableForModel`.
278	/// The `qwen3-` prefix makes `Auto` select the qwen3 JSON parser exactly as it
279	/// would for `models/Qwen3-4B` in production.
280	fn qwen_model_dir() -> Result<TempDir> {
281	    let dir = tempfile::Builder::new()
282	        .prefix("qwen3-sim-toolcall-")
283	        .tempdir()
284	        .context("failed to create qwen-prefixed temp model dir")?;
285	
286	    fs::write(dir.path().join("tokenizer.json"), fuse_tokenizer_json()?)
287	        .context("failed to write tool-call tokenizer.json")?;
288	    fs::write(
289	        dir.path().join("tokenizer_config.json"),
290	        serde_json::to_string_pretty(&json!({
291	            "unk_token": "<unk>",
292	            "eos_token": "<|endoftext|>",
293	            "tokenizer_class": "PreTrainedTokenizerFast",
294	            // Minimal template so /v1/chat/completions can render messages.
295	            "chat_template": "{% for message in messages %}{{ message['content'] }}{% endfor %}"
296	        }))?,
297	    )
298	    .context("failed to write tokenizer_config.json")?;
299	    fs::write(
300	        dir.path().join("config.json"),
301	        serde_json::to_string_pretty(&json!({
302	            "model_type": "pegainfer_sim",
303	            "max_position_embeddings": 128,
304	            "eos_token_id": 6,
305	            "vocab_size": 7
306	        }))?,
307	    )
308	    .context("failed to write config.json")?;
309	
310	    Ok(dir)
311	}
312	
313	/// WordLevel tokenizer + `Fuse` decoder whose ids 1/2/3 detokenize to the three
314	/// tool-call chunks. The sim emits token *ids*, detokenized by this served
315	/// `tokenizer.json`; a vocab of real words cannot spell a tool call, so the
316	/// vocab entries are the raw chunks and `Fuse` concatenates them byte-for-byte.
317	fn fuse_tokenizer_json() -> Result<String> {
318	    let mut vocab = Map::new();
319	    vocab.insert("<unk>".to_string(), json!(0));
320	    vocab.insert(CHUNK_1.to_string(), json!(1));
321	    vocab.insert(CHUNK_2.to_string(), json!(2));
322	    vocab.insert(CHUNK_3.to_string(), json!(3));
323	    // The frontend also runs `reasoning_parser: Auto`, which on a `qwen` path
324	    // selects the qwen3 reasoning parser and requires `<think>`/`</think>`
325	    // delimiter tokens to exist (real Qwen3 tokenizers carry them). Without
326	    // these the chat request 500s before ever reaching the tool parser.
327	    vocab.insert("<think>".to_string(), json!(4));
328	    vocab.insert("</think>".to_string(), json!(5));
329	    // EOS id padded onto the script in `ToolCallSimServer::spawn` (see there for why).
330	    vocab.insert("<|endoftext|>".to_string(), json!(6));
331	
332	    let special = |id: u32, content: &str| {
333	        json!({
334	            "id": id,
335	            "content": content,
336	            "single_word": false,
337	            "lstrip": false,
338	            "rstrip": false,
339	            "normalized": false,
340	            "special": true
341	        })
342	    };
343	    let tokenizer = json!({
344	        "version": "1.0",
345	        "truncation": null,
346	        "padding": null,
347	        "added_tokens": [
348	            special(0, "<unk>"),
349	            special(4, "<think>"),
350	            special(5, "</think>"),
351	            special(6, "<|endoftext|>")
352	        ],
353	        "normalizer": null,
354	        "pre_tokenizer": { "type": "Whitespace" },
355	        "post_processor": null,
356	        // Fuse concatenates decoded tokens with no separator, so the chunks
357	        // reassemble byte-for-byte.
358	        "decoder": { "type": "Fuse" },
359	        "model": {
360	            "type": "WordLevel",
361	            "vocab": vocab,
362	            "unk_token": "<unk>"
363	        }
364	    });
365	    serde_json::to_string_pretty(&tokenizer).context("failed to serialize fuse tokenizer")
366	}
367	
368	fn test_client() -> Result<Client> {
369	    Client::builder()
370	        .timeout(HTTP_TIMEOUT)
371	        .build()
372	        .context("failed to build HTTP test client")
373	}
374	
375	async fn wait_for_health(client: &Client, base_url: &str) -> Result<()> {
376	    let health_url = format!("{base_url}/health");
377	    let deadline = tokio::time::Instant::now() + Duration::from_secs(30);
378	    loop {
379	        if tokio::time::Instant::now() >= deadline {
380	            bail!("timed out waiting for sim frontend health at {health_url}");
381	        }
382	        match client
383	            .get(&health_url)
384	            .timeout(Duration::from_secs(1))
385	            .send()
386	            .await
387	        {
388	            Ok(response) if response.status().is_success() => return Ok(()),
389	            Ok(_) | Err(_) => tokio::time::sleep(Duration::from_millis(100)).await,
390	        }
391	    }
392	}
393	
394	fn reserve_loopback_port() -> Result<u16> {
395	    let listener = TcpListener::bind(("127.0.0.1", 0))
396	        .context("failed to reserve loopback port for tool-call e2e test")?;
397	    Ok(listener.local_addr()?.port())
398	}
399	
400	#[test]
401	fn scripted_chunks_concatenate_to_expected_payload() {
402	    let joined = format!("{CHUNK_1}{CHUNK_2}{CHUNK_3}");
403	    assert_eq!(
404	        joined,
405	        "<tool_call>\n{\"name\": \"get_weather\", \"arguments\": {\"location\": \"SF\"}}\n</tool_call>"
406	    );
407	    // The inner JSON object must be valid on its own.
408	    let inner = joined
409	        .trim_start_matches("<tool_call>")
410	        .trim()
411	        .trim_end_matches("</tool_call>")
412	        .trim();
413	    let parsed: Value = serde_json::from_str(inner).expect("inner tool-call JSON is valid");
414	    assert_eq!(parsed["name"], json!("get_weather"));
415	    assert_eq!(parsed["arguments"]["location"], json!("SF"));
416	}
