299	fn replay_profiled_worker(profile: &LoadedEngineProfile) -> Result<Vec<PlanTrace>> {
300	    let mut worker = WorkerState::new(profile.scheduler.clone())?;
301	    for request in [
302	        WorkerRequest {
303	            id: 1_u64,
304	            prompt_tokens: 4,
305	            output_tokens: 2,
306	        },
307	        WorkerRequest {
308	            id: 2,
309	            prompt_tokens: 2,
310	            output_tokens: 2,
311	        },
312	        WorkerRequest {
313	            id: 3,
314	            prompt_tokens: 1,
315	            output_tokens: 2,
316	        },
317	    ] {
318	        assert!(matches!(
319	            worker.submit(request)?,
320	            pegainfer_sim::worker::SubmissionResult::Queued
321	        ));
322	    }
323	
324	    let mut trace = Vec::new();
325	    let mut observed_waiting = false;
326	    while !worker.is_idle() {
327	        observed_waiting |= worker.waiting_len() > 0;
328	        let plan = worker
329	            .plan_step()?
330	            .context("worker with active requests produced no step")?;
331	        let step_id = plan.id();
332	        let shape = plan.shape();
333	        let estimate = profile.estimate_step(shape)?;
334	        assert!(matches!(
335	            estimate.source,
336	            pegainfer_sim::profile::StepTimingSource::GridInterpolation
337	        ));
338	        assert!(
339	            shape.decode_reqs <= profile.scheduler.max_num_seqs,
340	            "decode request count exceeded scheduler capacity: {shape:?}"
341	        );
342	        assert!(
343	            shape.decode_reqs + shape.prefill_tokens_in_step
344	                <= profile.scheduler.max_num_batched_tokens,
345	            "step token count exceeded scheduler capacity: {shape:?}"
346	        );
347	        let entry = PlanTrace {
348	            shape,
349	            duration_us: estimate.duration_us,
350	            admitted: plan.admitted().to_vec(),
351	            prefill: plan
352	                .prefill()
353	                .iter()
354	                .map(|work| (work.request_id, work.tokens))
355	                .collect(),
356	            decode: plan
357	                .decode()
358	                .iter()
359	                .map(|work| (work.request_id, work.context_tokens))
360	                .collect(),
361	        };
362	        worker.complete_step(step_id)?;
363	        trace.push(entry);
364	    }
365	    assert!(observed_waiting, "replay must exercise sequence admission");
366	    Ok(trace)
367	}
