720	/// A request that is admitted and then aborted produces no tokens to carry its
721	/// prefix delta: only the cached-token metadata record, then nothing. The
722	/// stepped bridge still has to ship that delta in a stats-only batch, or the
723	/// lookup is lost for good (and a later batch must not re-send it).
724	#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
725	async fn aborted_request_still_ships_its_prefix_lookup() -> Result<()> {
726	    let server = SimServer::spawn_aborting_prefix_cache().await?;
727	    let client = test_client()?;
728	    let abandoning = test_client_with_timeout(ABORT_CLIENT_TIMEOUT)?;
729	
730	    let body = json!({
731	        "model": server.model_name,
732	        "prompt": vec![1u32; PREFIX_PROMPT],
733	        "max_tokens": 4,
734	        "temperature": 0.0,
735	        "ignore_eos": true,
736	    })
737	    .to_string();
738	
739	    // Abandoned mid-prefill: admitted (so its lookup was counted), never served.
740	    // Asserting the timeout is what keeps this an abort rather than a normal
741	    // completion — with `let _ =` the test would also pass if it finished.
742	    match abandoning
743	        .post(format!("{}/v1/completions", server.base_url))
744	        .header(reqwest::header::CONTENT_TYPE, "application/json")
745	        .body(body.clone())
746	        .send()
747	        .await
748	    {
749	        Ok(response) => panic!(
750	            "the abandoned request was served instead of timing out: {}",
751	            response.status()
752	        ),
753	        Err(error) => assert!(
754	            error.is_timeout(),
755	            "the abandoned request failed for the wrong reason: {error}"
756	        ),
757	    }
758	
759	    // A second request drives the next step — the moment a stranded delta would
760	    // be flushed, and the moment a re-sent one would double the total.
761	    client
762	        .post(format!("{}/v1/completions", server.base_url))
763	        .header(reqwest::header::CONTENT_TYPE, "application/json")
764	        .body(body)
765	        .send()
766	        .await?
767	        .error_for_status()?;
768	
769	    // All four families carry both lookups exactly once. Only the second
770	    // request emits tokens, yet the first one's lookup must land too: the
771	    // totals are those of two admitted requests, split into the local hits and
772	    // the externally-restored hits, with no delta replayed on top.
773	    let queries = 2.0 * PREFIX_PROMPT as f64;
774	    let external_queries = 2.0 * (PREFIX_PROMPT - PREFIX_LOCAL_HITS) as f64;
775	    wait_for_metrics(
776	        &client,
777	        &server.base_url,
778	        &[
779	            ("vllm:prefix_cache_queries_total", "0", queries),
780	            (
781	                "vllm:prefix_cache_hits_total",
782	                "0",
783	                2.0 * PREFIX_LOCAL_HITS as f64,
784	            ),
785	            (
786	                "vllm:external_prefix_cache_queries_total",
787	                "0",
788	                external_queries,
789	            ),
790	            (
791	                "vllm:external_prefix_cache_hits_total",
792	                "0",
793	                2.0 * PREFIX_EXTERNAL_HITS as f64,
794	            ),
795	        ],
796	        &server.model_name,
797	    )
798	    .await?;
799	
800	    server.shutdown().await
801	}
