1043	/// One expected exposition line: metric name, `engine` label, any further
1044	/// labels, and the value it must carry.
1045	type ExpectedMetric<'a> = (&'a str, &'a str, &'a [(&'a str, &'a str)], f64);
1046	
1047	/// [`wait_for_metrics`] plus arbitrary extra labels, for families keyed by more
1048	/// than engine and model — the per-position spec-decode counter adds `position`.
1049	async fn wait_for_labeled_metrics(
1050	    client: &Client,
1051	    base_url: &str,
1052	    expected: &[ExpectedMetric<'_>],
1053	    model_name: &str,
1054	) -> Result<()> {
1055	    let metrics_url = format!("{base_url}/metrics");
1056	    let deadline = tokio::time::Instant::now() + Duration::from_secs(10);
1057	    let mut last_metrics = String::new();
1058	    loop {
1059	        if tokio::time::Instant::now() >= deadline {
1060	            bail!("timed out waiting for scheduler metrics at {metrics_url}:\n{last_metrics}");
1061	        }
1062	
1063	        if let Ok(response) = client.get(&metrics_url).send().await {
1064	            if let Ok(response) = response.error_for_status() {
1065	                if let Ok(metrics) = response.text().await {
1066	                    let all_found =
1067	                        expected
1068	                            .iter()
1069	                            .all(|(metric, engine, labels, expected_value)| {
1070	                                metrics.lines().any(|line| {
1071	                                    line.starts_with(metric)
1072	                                        && line.contains(&format!("engine=\"{engine}\""))
1073	                                        && line.contains(&format!("model_name=\"{model_name}\""))
1074	                                        && labels.iter().all(|(name, value)| {
1075	                                            line.contains(&format!("{name}=\"{value}\""))
1076	                                        })
1077	                                        && line
1078	                                            .rsplit_once(' ')
1079	                                            .and_then(|(_, value)| value.parse::<f64>().ok())
1080	                                            .is_some_and(|value| {
1081	                                                (value - expected_value).abs() < 1e-9
1082	                                            })
1083	                                })
1084	                            });
1085	                    if all_found {
1086	                        return Ok(());
1087	                    }
1088	                    last_metrics = metrics;
1089	                }
1090	            }
1091	        }
1092	        tokio::time::sleep(Duration::from_millis(50)).await;
1093	    }
1094	}
