1154	/// Keeps every request it admits running until the request is aborted.
1155	struct HoldScheduler {
1156	    queued: Vec<RequestId>,
1157	    running: Vec<RequestId>,
1158	    admitted: Arc<AtomicBool>,
1159	}
1160	
1161	impl Scheduler for HoldScheduler {
1162	    fn submit(&mut self, request: QueuedRequest) {
1163	        self.queued.push(request.id);
1164	    }
1165	
1166	    fn step(&mut self, ledger: &mut RequestLedger) -> Result<()> {
1167	        for id in self.queued.drain(..) {
1168	            ledger.admit(id);
1169	            self.running.push(id);
1170	            self.admitted.store(true, Ordering::Release);
1171	        }
1172	        self.running.retain(|&id| {
1173	            if ledger.is_aborted(id) {
1174	                ledger.retire(id);
1175	                false
1176	            } else {
1177	                true
1178	            }
1179	        });
1180	        Ok(())
1181	    }
1182	
1183	    fn metrics(&self) -> SchedulerMetrics {
1184	        SchedulerMetrics {
1185	            num_running_reqs: self.running.len() as u64,
1186	            num_waiting_reqs: self.queued.len() as u64,
1187	            ..SchedulerMetrics::default()
1188	        }
1189	    }
1190	}
