1192	/// One prefix-cache lookup per admitted request, taken from a fixed script of
1193	/// turns, published as cumulative totals the way a tiered engine does; each
1194	/// request then finishes after one token.
1195	struct TieredPrefixCacheScheduler {
1196	    turns: std::vec::IntoIter<PrefixCacheCounters>,
1197	    queued: Vec<RequestId>,
1198	    totals: PrefixCacheCounters,
1199	}
1200	
1201	impl Scheduler for TieredPrefixCacheScheduler {
1202	    fn submit(&mut self, request: QueuedRequest) {
1203	        self.queued.push(request.id);
1204	    }
1205	
1206	    fn step(&mut self, ledger: &mut RequestLedger) -> Result<()> {
1207	        for id in self.queued.drain(..) {
1208	            ledger.admit(id);
1209	            let turn = self.turns.next().context("no scripted turn left")?;
1210	            self.totals.queries += turn.queries;
1211	            self.totals.hits += turn.hits;
1212	            self.totals.host_queries += turn.host_queries;
1213	            self.totals.host_hits += turn.host_hits;
1214	            self.totals.external_unspecified_hits += turn.external_unspecified_hits;
1215	            ledger.push_tokens(id, &[0], &[]);
1216	            ledger.finish(id, FinishReason::Length);
1217	        }
1218	        Ok(())
1219	    }
1220	
1221	    fn metrics(&self) -> SchedulerMetrics {
1222	        SchedulerMetrics {
1223	            num_waiting_reqs: self.queued.len() as u64,
1224	            prefix_cache: Some(self.totals),
1225	            ..SchedulerMetrics::default()
1226	        }
1227	    }
1228	}
