1590	async fn reasoning_effort_extremes_are_mapped_onto_the_templates_vocabulary() -> Result<()> {
1591	    let server = SimServer::spawn_with_model_dir(model_dir_with_effort_guard()?).await?;
1592	    let client = test_client()?;
1593	
1594	    let chat = |body: Value| {
