1604	            let text = response.text().await?;
1605	            anyhow::Ok((status, text))
1606	        }
1607	    };
1608	
1609	    // Without the rewrite each of these hits the template's reject branch; the
1610	    // middleware maps them onto `xhigh` / `low` before the renderer sees them.
1611	    for effort in ["high", "max", "minimal"] {
1612	        let (status, text) = chat(json!({
1613	            "model": MODEL_NAME,
