1623	            );
1624	        }
1625	    }
1626	
1627	    // Values the template already accepts, and `none`, which the renderer turns
1628	    // into enable_thinking=false so the guard never runs.
1629	    for effort in ["xhigh", "medium", "low", "none"] {
1630	        let (status, text) = chat(json!({
1631	            "model": MODEL_NAME,
1632	            "messages": [{"role": "user", "content": "alpha beta"}],
1633	            "max_tokens": 2,
