1663	/// A per-request template whose effort vocabulary is the *inverse* of the
1664	/// served default's: it accepts `low|high|max` and raises on anything else,
1665	/// so `xhigh` — what the default-template mapping produces — is rejected here.
1666	const ACCEPTING_EFFORT_TEMPLATE: &str = r"{%- set resolved = reasoning_effort|default('high') %}{%- if resolved not in ('low', 'high', 'max') %}{{ raise_exception('Unexpected reasoning effort ' ~ reasoning_effort) }}{%- endif %}{% for message in messages %}{{ message.content }}{% endfor %}";
1667	
1668	/// The startup probe measures the checkpoint's default template, so its verdict
1669	/// has no authority over a request that overrides it. `reasoning_effort:"high"`
1670	/// with the override above must reach the renderer verbatim: rewriting it to
1671	/// `xhigh` on the default's authority would turn a working request into a
1672	/// render failure.
1673	#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
1674	async fn a_per_request_chat_template_override_keeps_its_own_effort_vocabulary() -> Result<()> {
1675	    let server = SimServer::spawn_with_model_dir(model_dir_with_effort_guard()?).await?;
1676	    let client = test_client()?;
1677	
1678	    let chat = |effort: String| {
1679	        let client = &client;
1680	        let base_url = server.base_url.clone();
1681	        async move {
1682	            let response = client
1683	                .post(format!("{base_url}/v1/chat/completions"))
1684	                .json(&json!({
1685	                    "model": MODEL_NAME,
1686	                    "messages": [{"role": "user", "content": "alpha beta"}],
1687	                    "max_tokens": 2,
1688	                    "temperature": 0.0,
1689	                    "reasoning_effort": effort,
1690	                    "chat_template": ACCEPTING_EFFORT_TEMPLATE
1691	                }))
1692	                .send()
1693	                .await?;
1694	            let status = response.status();
1695	            let text = response.text().await?;
1696	            anyhow::Ok((status, text))
1697	        }
1698	    };
1699	
1700	    let (status, text) = chat("high".to_string()).await?;
1701	    if !status.is_success() {
1702	        bail!("an override that accepts `high` must receive it verbatim, got {status}: {text}");
1703	    }
1704	
1705	    // Control: the override's guard is live and its vocabulary really is the
1706	    // inverse one, so the request above passed because the layer stayed out.
1707	    let (status, text) = chat("xhigh".to_string()).await?;
1708	    if status.is_success() {
1709	        bail!("the override rejects `xhigh`, so its guard must fail this render: {text}");
1710	    }
