2016	fn parse_terminal_sse_chunks(stream: &str) -> Result<Vec<Value>> {
2017	    let normalized = stream.replace("\r\n", "\n").replace('\r', "\n");
2018	    let mut payloads = Vec::new();
2019	    let mut data_lines = Vec::new();
2020	
2021	    for line in normalized.split_terminator('\n') {
2022	        if line.is_empty() {
2023	            if !data_lines.is_empty() {
2024	                payloads.push(data_lines.join("\n"));
2025	                data_lines.clear();
2026	            }
2027	            continue;
2028	        }
2029	        if line.starts_with(':') {
2030	            continue;
2031	        }
2032	
2033	        let (field, value) = line.split_once(':').unwrap_or((line, ""));
2034	        if field == "data" {
2035	            data_lines.push(value.strip_prefix(' ').unwrap_or(value));
2036	        }
2037	    }
2038	    if !data_lines.is_empty() {
2039	        bail!("streaming response ended before its final SSE event was dispatched: {stream}");
2040	    }
2041	
2042	    let done_count = payloads
2043	        .iter()
2044	        .filter(|payload| payload.as_str() == "[DONE]")
2045	        .count();
2046	    if done_count != 1 {
2047	        bail!("streaming response must contain exactly one data: [DONE]: {stream}");
2048	    }
2049	    if payloads.last().map(String::as_str) != Some("[DONE]") {
2050	        bail!("streaming response must end with data: [DONE]: {stream}");
2051	    }
2052	
2053	    payloads[..payloads.len() - 1]
2054	        .iter()
2055	        .map(|payload| serde_json::from_str(payload))
2056	        .collect::<std::result::Result<Vec<_>, _>>()
2057	        .context("failed to parse streaming chunks")
2058	}
