use std::fs;
use std::net::TcpListener;
use std::sync::Arc;
use std::sync::atomic::AtomicBool;
use std::sync::atomic::Ordering;
use std::time::Duration;
use std::time::Instant;

use anyhow::Context;
use anyhow::Result;
use anyhow::anyhow;
use anyhow::bail;
use pegainfer_frontend::engine::Engine;
use pegainfer_frontend::engine::EngineInfo;
use pegainfer_frontend::engine::FinishReason;
use pegainfer_frontend::engine::LiveScheduler;
use pegainfer_frontend::engine::PrefixCacheCounters;
use pegainfer_frontend::engine::QueuedRequest;
use pegainfer_frontend::engine::RequestId;
use pegainfer_frontend::engine::RequestLedger;
use pegainfer_frontend::engine::Scheduler;
use pegainfer_frontend::engine::SchedulerMetrics;
use pegainfer_frontend::engine::spawn_scheduler;
use pegainfer_sim::SimulatedEngineConfig;
use pegainfer_sim::profile::EngineProfile;
use pegainfer_sim::profile::LoadedEngineProfile;
use pegainfer_sim::profile::StepShape;
use pegainfer_sim::start_engine;
use pegainfer_sim::start_engine_with_partitions;
use pegainfer_sim::worker::WorkerRequest;
use pegainfer_sim::worker::WorkerState;
use reqwest::Client;
use serde_json::Value;
use serde_json::json;
use tempfile::TempDir;
use tokio::sync::oneshot;
use tokio::task::JoinHandle;
use tokio_util::sync::CancellationToken;

const HTTP_TIMEOUT: Duration = Duration::from_secs(10);
const MODEL_NAME: &str = "pegainfer-sim-e2e";
const METRICS_MODEL_NAME: &str = "pegainfer-sim-e2e-metrics";
const SLOW_METRICS_MODEL_NAME: &str = "pegainfer-sim-e2e-slow-metrics";
const SPEC_METRICS_MODEL_NAME: &str = "pegainfer-sim-e2e-spec-metrics";
const PREFIX_METRICS_MODEL_NAME: &str = "pegainfer-sim-e2e-prefix-metrics";
const PROFILE_GATE_MODEL_NAME: &str = "pegainfer-sim-online-gate";
const ZERO_COST_MODEL_NAME: &str = "pegainfer-sim-zero-cost";
/// The pretend drafter the spec-metrics server runs: `K` and how many of those
/// draft tokens each verify step accepts.
const SPEC_K: usize = 3;
const SPEC_ACCEPTED: usize = 2;
const ABORT_METRICS_MODEL_NAME: &str = "pegainfer-sim-e2e-abort-metrics";
const PREFIX_MISS_METRICS_MODEL_NAME: &str = "pegainfer-sim-e2e-prefix-miss-metrics";
const PREFIX_LOGPROBS_MODEL_NAME: &str = "pegainfer-sim-e2e-prefix-logprobs-metrics";
/// Long enough that a request is admitted (counting its lookup) well before it
/// can emit a token, so abandoning it leaves a delta with no output to ride.
const ABORT_TTFT_MS: f64 = 400.0;
/// Short enough that the client gives up inside that prefill window.
const ABORT_CLIENT_TIMEOUT: Duration = Duration::from_millis(60);
/// The pretend lookup the prefix-metrics server reports on every admitted
/// ordinary request: 8 prompt tokens queried, 5 found in local KV and 2 of the
/// remainder restored from the connector.
const PREFIX_PROMPT: usize = 8;
const PREFIX_LOCAL_HITS: usize = 5;
const PREFIX_EXTERNAL_HITS: usize = 2;
const SERVER_START_ATTEMPTS: usize = 5;

struct SimServer {
    base_url: String,
    model_name: String,
    shutdown: CancellationToken,
    task: JoinHandle<Result<()>>,
    _model_dir: TempDir,
}

impl SimServer {
    async fn spawn() -> Result<Self> {
        Self::spawn_with_model_dir(model_dir_with_minimal_metadata()?).await
    }

    async fn spawn_partitioned() -> Result<Self> {
        Self::spawn_with_config(
            model_dir_with_minimal_metadata()?,
            2,
            METRICS_MODEL_NAME,
            SimulatedEngineConfig::new(0.0, 1000.0, 0.0, 1)?,
        )
        .await
    }

    /// A single engine whose every decode step is a verify step, so the
    /// stepped bridge has spec-decode counters to stamp onto its batches.
    async fn spawn_with_drafter() -> Result<Self> {
        Self::spawn_with_config(
            model_dir_with_minimal_metadata()?,
            1,
            SPEC_METRICS_MODEL_NAME,
            SimulatedEngineConfig::new(0.0, 1000.0, 0.0, 1)?
                .with_speculative_decoding(SPEC_K, SPEC_ACCEPTED),
        )
        .await
    }

    /// A single engine that reports a scripted prefix lookup on every admitted
    /// request, so the stepped bridge has prefix-cache counters (local and
    /// external) to stamp onto its batches. Each server gets its own name
    /// because they share one process-wide Prometheus registry: two tests
    /// driving the same `model_name` would add into the same series and each
    /// would then see the other's totals.
    async fn spawn_with_prefix_cache_as(model_name: &'static str) -> Result<Self> {
        Self::spawn_with_config(
            model_dir_with_minimal_metadata()?,
            1,
            model_name,
            SimulatedEngineConfig::new(0.0, 1000.0, 0.0, 1)?
                .with_prefix_cache(PREFIX_LOCAL_HITS, PREFIX_EXTERNAL_HITS),
        )
        .await
    }

    /// As `spawn_with_prefix_cache_as`, but the scripted lookup matches nothing, so the counters must
    /// show a query with no hit rather than a cache that was never asked.
    async fn spawn_with_miss_prefix_cache() -> Result<Self> {
        Self::spawn_with_config(
            model_dir_with_minimal_metadata()?,
            1,
            PREFIX_MISS_METRICS_MODEL_NAME,
            SimulatedEngineConfig::new(0.0, 1000.0, 0.0, 1)?.with_prefix_cache(0, 0),
        )
        .await
    }

    /// A scripted lookup plus a slow prefill: the request counts its lookup on
    /// admission and is then abandoned without ever emitting a token.
    async fn spawn_aborting_prefix_cache() -> Result<Self> {
        Self::spawn_with_config(
            model_dir_with_minimal_metadata()?,
            1,
            ABORT_METRICS_MODEL_NAME,
            SimulatedEngineConfig::new(ABORT_TTFT_MS, 1000.0, 0.0, 1)?
                .with_prefix_cache(PREFIX_LOCAL_HITS, PREFIX_EXTERNAL_HITS),
        )
        .await
    }

    async fn spawn_slow() -> Result<Self> {
        Self::spawn_with_config(
            model_dir_with_minimal_metadata()?,
            1,
            SLOW_METRICS_MODEL_NAME,
            SimulatedEngineConfig::new(0.0, 1000.0, 80.0, 1)?,
        )
        .await
    }

    async fn spawn_with_model_dir(model_dir: TempDir) -> Result<Self> {
        Self::spawn_with_config(
            model_dir,
            1,
            MODEL_NAME,
            SimulatedEngineConfig::new(0.0, 1000.0, 0.0, 1)?,
        )
        .await
    }

    async fn spawn_with_config(
        model_dir: TempDir,
        engine_count: usize,
        model_name: &str,
        config: SimulatedEngineConfig,
    ) -> Result<Self> {
        let mut last_error = None;
        for attempt in 1..=SERVER_START_ATTEMPTS {
            match Self::spawn_once(&model_dir, engine_count, model_name, config.clone()).await {
                Ok(started) => {
                    return Ok(Self {
                        base_url: started.base_url,
                        model_name: started.model_name,
                        shutdown: started.shutdown,
                        task: started.task,
                        _model_dir: model_dir,
                    });
                }
                Err(error) => {
                    last_error = Some(error);
                    if attempt < SERVER_START_ATTEMPTS {
                        tokio::time::sleep(Duration::from_millis(100)).await;
                    }
                }
            }
        }

        Err(last_error.unwrap_or_else(|| anyhow!("sim frontend startup was not attempted")))
            .with_context(|| {
                format!("failed to start sim frontend after {SERVER_START_ATTEMPTS} attempts")
            })
    }

    async fn spawn_once(
        model_dir: &TempDir,
        engine_count: usize,
        model_name: &str,
        config: SimulatedEngineConfig,
    ) -> Result<StartedSimServer> {
        let port = reserve_loopback_port()?;
        let base_url = format!("http://127.0.0.1:{port}");
        let shutdown = CancellationToken::new();
        let engine = start_engine_with_partitions(&config, engine_count);
        let server_shutdown = shutdown.clone();
        let served_model_name = model_name.to_string();
        let started_model_name = served_model_name.clone();
        let model_path_buf = model_dir.path().to_path_buf();
        let mut task = tokio::spawn(async move {
            pegainfer_frontend::vllm::serve_with_engine_count(
                std::future::ready(Ok(engine.into())),
                &model_path_buf,
                vec![served_model_name],
                pegainfer_frontend::vllm::ParserSelection::Auto,
                port,
                Some(128),
                engine_count,
                server_shutdown,
            )
            .await
        });

        let client = test_client()?;
        let health_result = tokio::select! {
            result = wait_for_health(&client, &base_url) => result,
            result = &mut task => {
                return match result {
                    Ok(Ok(())) => Err(anyhow!("sim frontend exited before becoming healthy")),
                    Ok(Err(error)) => Err(error).context("sim frontend exited before becoming healthy"),
                    Err(error) => Err(error).context("sim frontend task panicked"),
                };
            }
        };

        if let Err(error) = health_result {
            shutdown.cancel();
            let _ = tokio::time::timeout(Duration::from_secs(10), task).await;
            return Err(error);
        }

        Ok(StartedSimServer {
            base_url,
            model_name: started_model_name,
            shutdown,
            task,
        })
    }

    async fn shutdown(self) -> Result<()> {
        self.shutdown.cancel();
        tokio::time::timeout(Duration::from_secs(10), self.task)
            .await
            .context("timed out waiting for sim frontend shutdown")?
            .context("sim frontend task panicked")?
    }
}

struct StartedSimServer {
    base_url: String,
    model_name: String,
    shutdown: CancellationToken,
    task: JoinHandle<Result<()>>,
}

#[derive(Debug, Eq, PartialEq)]
struct PlanTrace {
    shape: StepShape,
    duration_us: u64,
    admitted: Vec<u64>,
    prefill: Vec<(u64, u32)>,
    decode: Vec<(u64, u32)>,
}

fn profile_fixture(name: &str) -> Result<(TempDir, LoadedEngineProfile)> {
    let (profile_bytes, manifest_name, manifest_bytes): (&[u8], &str, &[u8]) = match name {
        "online-step-gate.json" => (
            include_bytes!("fixtures/online-step-gate.json"),
            "online-step-gate.manifest.json",
            include_bytes!("fixtures/online-step-gate.manifest.json"),
        ),
        "online-zero-cost.json" => (
            include_bytes!("fixtures/online-zero-cost.json"),
            "online-zero-cost.manifest.json",
            include_bytes!("fixtures/online-zero-cost.manifest.json"),
        ),
        other => bail!("unknown profile fixture {other}"),
    };
    let dir = tempfile::tempdir()?;
    fs::write(dir.path().join(name), profile_bytes)?;
    fs::write(dir.path().join(manifest_name), manifest_bytes)?;
    let profile = EngineProfile::load_from_path(dir.path().join(name))?;
    Ok((dir, profile))
}

fn replay_profiled_worker(profile: &LoadedEngineProfile) -> Result<Vec<PlanTrace>> {
    let mut worker = WorkerState::new(profile.scheduler.clone())?;
    for request in [
        WorkerRequest {
            id: 1_u64,
            prompt_tokens: 4,
            output_tokens: 2,
        },
        WorkerRequest {
            id: 2,
            prompt_tokens: 2,
            output_tokens: 2,
        },
        WorkerRequest {
            id: 3,
            prompt_tokens: 1,
            output_tokens: 2,
        },
    ] {
        assert!(matches!(
            worker.submit(request)?,
            pegainfer_sim::worker::SubmissionResult::Queued
        ));
    }

    let mut trace = Vec::new();
    let mut observed_waiting = false;
    while !worker.is_idle() {
        observed_waiting |= worker.waiting_len() > 0;
        let plan = worker
            .plan_step()?
            .context("worker with active requests produced no step")?;
        let step_id = plan.id();
        let shape = plan.shape();
        let estimate = profile.estimate_step(shape)?;
        assert!(matches!(
            estimate.source,
            pegainfer_sim::profile::StepTimingSource::GridInterpolation
        ));
        assert!(
            shape.decode_reqs <= profile.scheduler.max_num_seqs,
            "decode request count exceeded scheduler capacity: {shape:?}"
        );
        assert!(
            shape.decode_reqs + shape.prefill_tokens_in_step
                <= profile.scheduler.max_num_batched_tokens,
            "step token count exceeded scheduler capacity: {shape:?}"
        );
        let entry = PlanTrace {
            shape,
            duration_us: estimate.duration_us,
            admitted: plan.admitted().to_vec(),
            prefill: plan
                .prefill()
                .iter()
                .map(|work| (work.request_id, work.tokens))
                .collect(),
            decode: plan
                .decode()
                .iter()
                .map(|work| (work.request_id, work.context_tokens))
                .collect(),
        };
        worker.complete_step(step_id)?;
        trace.push(entry);
    }
    assert!(observed_waiting, "replay must exercise sequence admission");
    Ok(trace)
}

fn empty_model_dir() -> Result<TempDir> {
    tempfile::tempdir().context("failed to create temp model dir")
}

fn model_dir_with_minimal_metadata() -> Result<TempDir> {
    let dir = empty_model_dir()?;

    // The simulated frontend still builds the normal vLLM text/chat stack.
    // Token-id prompts avoid tokenizer encode work, but generated ids still
    // need a tokenizer for detokenization and a tiny config for metadata.
    fs::write(dir.path().join("tokenizer.json"), TINY_TOKENIZER_JSON)
        .context("failed to write tiny tokenizer.json")?;
    fs::write(
        dir.path().join("tokenizer_config.json"),
        TINY_TOKENIZER_CONFIG_JSON,
    )
    .context("failed to write tiny tokenizer_config.json")?;
    fs::write(dir.path().join("config.json"), TINY_CONFIG_JSON)
        .context("failed to write tiny config.json")?;

    Ok(dir)
}

#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn simulated_engine_serves_openai_completions_over_http() -> Result<()> {
    let server = SimServer::spawn().await?;
    let client = test_client()?;

    assert_models_endpoint(&client, &server.base_url, &server.model_name).await?;
    assert_non_streaming_completion_has_output(&client, &server.base_url, &server.model_name)
        .await?;
    assert_streaming_completion_emits_done(&client, &server.base_url, &server.model_name).await?;

    server.shutdown().await
}

#[test]
fn profiled_worker_replay_is_deterministic_and_bounded() -> Result<()> {
    let (_fixture_dir, profile) = profile_fixture("online-step-gate.json")?;
    let first = replay_profiled_worker(&profile)?;
    let second = replay_profiled_worker(&profile)?;

    assert_eq!(
        first, second,
        "same profile and arrivals must replay identically"
    );
    assert!(
        first
            .iter()
            .any(|step| step.shape.prefill_tokens_in_step > 0),
        "replay must include prefill work"
    );
    assert!(
        first.iter().any(|step| step.shape.decode_reqs > 0),
        "replay must include decode work"
    );
    assert!(
        first
            .iter()
            .map(|step| step.duration_us)
            .min()
            .is_some_and(|minimum| {
                first
                    .iter()
                    .map(|step| step.duration_us)
                    .any(|duration| duration > minimum)
            }),
        "grid pricing must vary across the replayed step shapes"
    );

    Ok(())
}

