) -> Result<()> {
    let stream = post_completion_stream(client, base_url, model_name).await?;
    if !stream.lines().any(|line| line.trim() == "data: [DONE]") {
        bail!("streaming completion did not emit terminal data: [DONE]: {stream}");
    }

